class Solution {
    int gcdInt(int a, int b) {
        while (b) { int t = a % b; a = b; b = t; }
        return a;
    }
public:
    long long gcdSum(vector<int>& nums) {
        vector<int> a;
        a.reserve(nums.size());
        int mx = 0;
        for (int x : nums) {
            mx = max(mx, x);
            a.push_back(gcdInt(x, mx));
        }
        sort(a.begin(), a.end());
        long long ans = 0;
        for (int i = 0, j = (int)a.size() - 1; i < j; ++i, --j)
            ans += gcdInt(a[i], a[j]);
        return ans;
    }
};
